		conn.add(alignedEntry, iri(conn, "caption"), conn.getValueFactory().createLiteral("aligned"), northArchive);
		conn.add(alignedEntry, iri(conn, "filed-in"), northArchive, northArchive);
		conn.add(plainEntry, iri(conn, "caption"), conn.getValueFactory().createLiteral("plain"), northArchive);
		conn.add(plainEntry, iri(conn, "filed-in"), iri(conn, "stale-archive"), northArchive);
		conn.add(redirectedEntry, iri(conn, "caption"), conn.getValueFactory().createLiteral("redirected"),
				southArchive);
		conn.add(redirectedEntry, iri(conn, "filed-in"), iri(conn, "other-archive"), southArchive);

		String optional = "OPTIONAL { ?entry :filed-in ?archive BIND(\"matched\" AS ?marker) }";
